/**
 * Feature: backgrounds.
 * Pre-installed looks for slides, in two kinds:
 *
 * Classic stills are pure CSS (gradients and conic rays), so they ship
 * inside the app on every machine with zero files to lose.
 *
 * Photos and Motion are generated by assets/backgrounds/generate.py
 * (see docs/backgrounds.md): 1920x1080 stills and short seamless video
 * loops under public/backgrounds/. Each falls back to a CSS gradient
 * when its file is missing, so a fresh clone never shows a broken
 * slide. Paths are relative, not absolute, so they also work when the
 * packaged app loads over file:// instead of a server.
 *
 * My Backgrounds are photos and videos the user adds from disk; the
 * desktop app keeps them in its data folder (see BackgroundPicker).
 */

export type BackgroundPreset = {
  id: string
  name: string
  kind: 'still' | 'video'
  /** CSS background, always rendered underneath (and alone for stills). */
  css: string
  /** Path or URL of the looping video, for motion presets. */
  video?: string
}

