/** A generated still: the image on top of a gradient that stands in until it loads. */
const photo = (id: string, name: string, fallback: string): BackgroundPreset => ({
  id,
  name,
  kind: 'still',
  css: `url('backgrounds/${id}.jpg') center / cover no-repeat, ${fallback}`,
})

/** A generated loop: its poster frame is the still look until the video plays. */
const motion = (id: string, name: string, fallback: string): BackgroundPreset => ({
  id,
  name,
  kind: 'video',
  css: `url('backgrounds/${id}.jpg') center / cover no-repeat, ${fallback}`,
  video: `backgrounds/${id}.webm`,
})

