/** A photo or video the user added; the URL points at the app's data folder. */
export function userBackground(file: { file: string; name: string; kind: 'still' | 'video'; url: string }): BackgroundPreset {
  return file.kind === 'video'
    ? { id: `mine:${file.file}`, name: file.name, kind: 'video', css: '#000000', video: file.url }
    : {
        id: `mine:${file.file}`,
        name: file.name,
        kind: 'still',
        css: `url("${file.url}") center / cover no-repeat, #000000`,
      }
}

